17	export class PBKDF2 {
18	  constructor(passphrase, salt, iterations = 1000) {
19	    if (!Number.isInteger(iterations)) {
20	      throw new TypeError('iterations must be an integer');
21	    }
22	
23	    if (iterations < 1) {
24	      throw new ValueError('iterations must be at least 1');
25	    }
26	
27	    this.passphraseBytes = normalizeInput(passphrase);
28	    this.saltBytes = normalizeInput(salt);
29	    this.iterations = iterations;
30	    this.blockIndex = 1;
31	    this.buffer = new Uint8Array(0);
32	    this.bufferOffset = 0;
33	  }
34	
35	  read(byteCount) {
36	    if (!Number.isInteger(byteCount) || byteCount < 0) {
37	      throw new RangeError('byteCount must be a non-negative integer');
38	    }
39	
40	    const output = new Uint8Array(byteCount);
41	    let written = 0;
42	
43	    while (written < byteCount) {
44	      if (this.bufferOffset >= this.buffer.length) {
45	        this.buffer = this.deriveBlock(this.blockIndex);
46	        this.blockIndex += 1;
47	        this.bufferOffset = 0;
48	      }
49	
50	      const available = this.buffer.length - this.bufferOffset;
51	      const remaining = byteCount - written;
52	      const chunkLength = available < remaining ? available : remaining;
53	
54	      output.set(this.buffer.subarray(this.bufferOffset, this.bufferOffset + chunkLength), written);
55	
56	      this.bufferOffset += chunkLength;
57	      written += chunkLength;
58	    }
59	
60	    return output;
61	  }
62	
63	  deriveBlock(blockIndex) {
64	    const blockInput = new Uint8Array(this.saltBytes.length + 4);
65	    blockInput.set(this.saltBytes);
66	    writeUint32BE(blockInput, this.saltBytes.length, blockIndex >>> 0);
67	
68	    let u = hmacSha1(this.passphraseBytes, blockInput);
69	    const accumulator = new Uint8Array(u);
70	
71	    for (let iteration = 1; iteration < this.iterations; iteration += 1) {
72	      u = hmacSha1(this.passphraseBytes, u);
73	      xorInto(accumulator, u);
74	    }
75	
76	    return accumulator;
77	  }
78	}
