10	export function derivePbkdf2Sha1(password, salt, iterations, derivedKeyLength) {
11	  if (!Number.isInteger(iterations) || iterations < 1) {
12	    throw new ValueError('iterations must be at least 1');
13	  }
14	
15	  if (!Number.isInteger(derivedKeyLength) || derivedKeyLength < 1) {
16	    throw new ValueError('derived key length must be at least 1');
17	  }
18	
19	  const passwordBytes = Buffer.from(password, 'utf8');
20	  const saltBytes = Buffer.from(salt, 'utf8');
21	  const blockCount = Math.ceil(derivedKeyLength / SHA1_DIGEST_LENGTH);
22	  const derived = Buffer.alloc(blockCount * SHA1_DIGEST_LENGTH);
23	
24	  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
25	    const block = deriveBlock(passwordBytes, saltBytes, iterations, blockIndex);
26	    block.copy(derived, (blockIndex - 1) * SHA1_DIGEST_LENGTH);
27	  }
28	
29	  return derived.subarray(0, derivedKeyLength);
30	}
