36	function deriveBlock(passwordBytes, saltBytes, iterations, blockIndex) {
37	  const blockIndexBytes = Buffer.allocUnsafe(4);
38	  blockIndexBytes.writeUInt32BE(blockIndex, 0);
39	
40	  let intermediate = hmacSha1(passwordBytes, saltBytes, blockIndexBytes);
41	  const accumulator = Buffer.from(intermediate);
42	
43	  for (let round = 1; round < iterations; round += 1) {
44	    intermediate = hmacSha1(passwordBytes, intermediate);
45	    xorInto(accumulator, intermediate);
46	  }
47	
48	  return accumulator;
49	}
